#!/usr/bin/env node
// Throwaway differential-test harness: /workspace/dataset/test7_executable (reference)
// vs `node /output/test7.mjs` (port). Input class: cli-semantics.
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test7_executable';
const PORT_ARGS = ['/output/test7.mjs'];
const REF_PROG = 'test7_executable';
const PORT_PROG = 'test7.mjs';

// Deterministic, identical env for both. COLUMNS unset -> argparse falls back to 80.
const baseEnv = { ...process.env };
delete baseEnv.COLUMNS;
delete baseEnv.NODE_OPTIONS;

function run(cmd, argv, env) {
  const r = spawnSync(cmd, argv, {
    env,
    encoding: 'buffer',
    maxBuffer: 64 * 1024 * 1024,
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  if (r.error) throw r.error;
  return {
    stdout: r.stdout ?? Buffer.alloc(0),
    stderr: r.stderr ?? Buffer.alloc(0),
    code: r.status,
    signal: r.signal,
  };
}

// The ONLY permitted difference: the program-name substring baked into
// usage/error text. Rewrite it in the reference bytes and nowhere else.
function normalizeRef(buf) {
  return Buffer.from(buf.toString('binary').split(REF_PROG).join(PORT_PROG), 'binary');
}

const A = 'Lm8qH}*x';
const B = 'salt_346554';
const C = 'Ad32jimv';

const cases = [];
const add = (name, argv, env = null) => cases.push({ name, argv, env });

// --- ordering permutations of the three required options (space form) ---
add('order a,b,c', ['--a', A, '--b', B, '--c', C]);
add('order a,c,b', ['--a', A, '--c', C, '--b', B]);
add('order b,a,c', ['--b', B, '--a', A, '--c', C]);
add('order b,c,a', ['--b', B, '--c', C, '--a', A]);
add('order c,a,b', ['--c', C, '--a', A, '--b', B]);
add('order c,b,a', ['--c', C, '--b', B, '--a', A]);

// --- equals-form vs space-form ---
add('all equals form', [`--a=${A}`, `--b=${B}`, `--c=${C}`]);
add('all equals, reversed order', [`--c=${C}`, `--b=${B}`, `--a=${A}`]);
add('mixed equals/space 1', [`--a=${A}`, '--b', B, `--c=${C}`]);
add('mixed equals/space 2', ['--a', A, `--b=${B}`, '--c', C]);
add('equals with empty value --a=', ['--a=', '--b', B, '--c', C]);
add('equals with empty value --b=', ['--a', A, '--b=', '--c', C]);
add('equals value containing =', ['--a=x=y', '--b', B, '--c', C]);
add('equals value that looks like an option', ['--a=--b', '--b', B, '--c', C]);

// --- help ---
add('--help alone', ['--help']);
add('-h alone', ['-h']);
add('--help before valid args', ['--help', '--a', A, '--b', B, '--c', C]);
add('--help after valid args', ['--a', A, '--b', B, '--c', C, '--help']);
add('-h in the middle of valid args', ['--a', A, '-h', '--b', B, '--c', C]);
add('--help with everything missing but an unknown opt', ['--help', '--zzz']);
add('--help=x (help takes no value)', ['--help=x']);
add('-h -h duplicated', ['-h', '-h']);
add('-hh (bundled short)', ['-hh']);

// --- abbreviated options (argparse prefix matching) ---
add('--h abbrev of --help', ['--h']);
add('--he abbrev of --help', ['--he']);
add('--hel abbrev of --help', ['--hel']);
add('--help exact', ['--help', '--a', A]);
add('--a is already full (no abbrev)', ['--a', A, '--b', B, '--c', C]);
add('--ab unknown (not an abbrev)', ['--ab', A, '--b', B, '--c', C]);
add('--aa unknown', ['--aa=1', '--b', B, '--c', C]);

// --- missing required options ---
add('no args at all', []);
add('only --a', ['--a', A]);
add('only --b', ['--b', B]);
add('only --c', ['--c', C]);
add('missing --a', ['--b', B, '--c', C]);
add('missing --b', ['--a', A, '--c', C]);
add('missing --c', ['--a', A, '--b', B]);
add('missing --b and --c', ['--a', A]);
add('missing --a and --c (order b only)', ['--b', B]);

// --- duplicated options (argparse: last wins) ---
add('duplicate --a', ['--a', 'first', '--a', A, '--b', B, '--c', C]);
add('duplicate all three', ['--a', 'x', '--b', 'y', '--c', 'z', '--a', A, '--b', B, '--c', C]);
add('duplicate --a equals then space', [`--a=x`, '--a', A, '--b', B, '--c', C]);
add('triple --c', ['--a', A, '--b', B, '--c', '1', '--c', '2', '--c', C]);

// --- unknown options ---
add('unknown long --d', ['--a', A, '--b', B, '--c', C, '--d', 'x']);
add('unknown short -a (single dash)', ['-a', A, '--b', B, '--c', C]);
add('unknown short -x', ['--a', A, '--b', B, '--c', C, '-x']);
add('unknown --A (case sensitivity)', ['--A', A, '--b', B, '--c', C]);
add('unknown -- alone-ish --=x', ['--=x', '--a', A, '--b', B, '--c', C]);
add('unknown option only', ['--nope']);
add('unknown before required-missing', ['--nope', '--a', A]);

// --- extra positionals ---
add('one extra positional', ['--a', A, '--b', B, '--c', C, 'extra']);
add('two extra positionals', ['--a', A, '--b', B, '--c', C, 'x', 'y']);
add('positional first', ['pos', '--a', A, '--b', B, '--c', C]);
add('positional in the middle', ['--a', A, 'pos', '--b', B, '--c', C]);
add('lone dash positional', ['-', '--a', A, '--b', B, '--c', C]);
add('empty-string positional', ['', '--a', A, '--b', B, '--c', C]);

// --- "--" separator ---
add('trailing -- after valid args', ['--a', A, '--b', B, '--c', C, '--']);
add('-- then a positional', ['--a', A, '--b', B, '--c', C, '--', 'pos']);
add('-- then option-looking positionals', ['--', '--a', A, '--b', B, '--c', C]);
add('-- alone', ['--']);
add('-- used to pass dash value', ['--a', '--', '--b', B, '--c', C]);
add('double -- ', ['--a', A, '--b', B, '--c', C, '--', '--']);
add('-- before --c value', ['--a', A, '--b', B, '--c', '--', 'x']);

// --- option-with-no-value ---
add('--a with no value (end)', ['--a']);
add('--b with no value (end)', ['--a', A, '--b']);
add('--c with no value (end)', ['--a', A, '--b', B, '--c']);
add('--a with no value, followed by --b', ['--a', '--b', B, '--c', C]);
add('--a followed by --a', ['--a', '--a', '--b', B, '--c', C]);
add('--c with no value then --', ['--a', A, '--b', B, '--c', '--']);

// --- dash-leading / negative-number-looking values ---
add('value with leading dash', ['--a', '-1', '--b', B, '--c', C]);
add('value -1 equals form', ['--a=-1', '--b', B, '--c', C]);
add('value --x space form', ['--a', '--x', '--b', B, '--c', C]);
add('value -5.5', ['--a', '-5.5', '--b', B, '--c', C]);
add('all-empty values', ['--a', '', '--b', '', '--c', '']);

// --- COLUMNS-sensitivity spot checks (same env for both) ---
{
  const narrow = { ...baseEnv, COLUMNS: '40' };
  add('--help with COLUMNS=40', ['--help'], narrow);
  add('missing required with COLUMNS=40', [], narrow);
  const wide = { ...baseEnv, COLUMNS: '200' };
  add('--help with COLUMNS=200', ['--help'], wide);
}

// --- run ---
const q = (s) => JSON.stringify(s);
const fmtArgv = (a) => '[' + a.map(q).join(', ') + ']';
const show = (buf) => (buf.length === 0 ? '(empty)' : JSON.stringify(buf.toString('utf8')));

let pass = 0;
const mismatches = [];

for (const c of cases) {
  const env = c.env ?? baseEnv;
  const ref = run(REF, c.argv, env);
  const port = run(process.execPath, [...PORT_ARGS, ...c.argv], env);

  const refOut = normalizeRef(ref.stdout);
  const refErr = normalizeRef(ref.stderr);

  const okOut = refOut.equals(port.stdout);
  const okErr = refErr.equals(port.stderr);
  const okCode = ref.code === port.code;

  // Sanity: flag if the raw reference text differed anywhere other than prog name,
  // i.e. make sure normalization actually only touched the prog substring.
  const normTouched =
    !refOut.equals(ref.stdout) || !refErr.equals(ref.stderr);

  if (okOut && okErr && okCode) {
    pass++;
    console.log(`PASS  ${c.name}${normTouched ? '  [prog-name normalized]' : ''}`);
  } else {
    mismatches.push({ c, ref, port, refOut, refErr, okOut, okErr, okCode });
    console.log(`FAIL  ${c.name}`);
  }
}

console.log('\n================ SUMMARY ================');
console.log(`total cases: ${cases.length}`);
console.log(`matching:    ${pass}`);
console.log(`mismatching: ${mismatches.length}`);

for (const m of mismatches) {
  console.log('\n---------------- MISMATCH ----------------');
  console.log(`case:  ${m.c.name}`);
  console.log(`argv:  ${fmtArgv(m.c.argv)}`);
  if (m.c.env && m.c.env.COLUMNS) console.log(`env:   COLUMNS=${m.c.env.COLUMNS}`);
  console.log(`exit code   reference=${m.ref.code}  port=${m.port.code}  ${m.okCode ? '(match)' : '(DIFFER)'}`);
  console.log(`stdout ${m.okOut ? '(match)' : '(DIFFER)'}`);
  if (!m.okOut) {
    console.log(`  expected(ref, prog-normalized): ${show(m.refOut)}`);
    console.log(`  actual(port):                   ${show(m.port.stdout)}`);
  }
  console.log(`stderr ${m.okErr ? '(match)' : '(DIFFER)'}`);
  if (!m.okErr) {
    console.log(`  expected(ref, prog-normalized): ${show(m.refErr)}`);
    console.log(`  actual(port):                   ${show(m.port.stderr)}`);
  }
}
if (mismatches.length === 0) console.log('\nALL CASES MATCH');

