add('eq empty value --a=', ['--a=', '--b', B, '--c', C]);
add('eq empty value --b=', ['--a', A, '--b=', '--c', C]);
add('eq empty value --c=', ['--a', A, '--b', B, '--c=']);
add('eq value containing =', ['--a=x=y', '--b', B, '--c', C]);
add('eq value looks like option', ['--a=--b', '--b', B, '--c', C]);
add('eq value = -h', ['--a=-h', '--b', B, '--c', C]);
add('eq value with spaces', ['--a=a b c', '--b', B, '--c', C]);
add('eq value with newline/tab', ['--a=x\ny\tz', '--b', B, '--c', C]);
add('space value with spaces', ['--a', 'a b c', '--b', B, '--c', C]);
/* help */
add('--help alone', ['--help']);
add('-h alone', ['-h']);
add('--help before valid args', ['--help', '--a', A, '--b', B, '--c', C]);
add('--help after valid args', ['--a', A, '--b', B, '--c', C, '--help']);
add('-h mid valid args', ['--a', A, '-h', '--b', B, '--c', C]);
add('--help + unknown opt', ['--help', '--zzz']);
add('--help=x', ['--help=x']);
add('-h=1', ['-h=1']);
