  const okCode = refReal.code === port.code && refAlias.code === port.code;
  const ok = okNormOut && okNormErr && okRawOut && okRawErr && okCode;

  if (ok) { pass++; console.log(`PASS  ${c.name}`); }
  else {
    mismatches.push({ c, refReal, refAlias, port, nOut, nErr, okNormOut, okNormErr, okRawOut, okRawErr, okCode });
    console.log(`FAIL  ${c.name}`);
  }
}

console.log('\n================ SUMMARY ================');
console.log(`total cases: ${cases.length}`);
console.log(`matching:    ${pass}`);
console.log(`mismatching: ${mismatches.length}`);
for (const m of mismatches) {
  console.log('\n---------------- MISMATCH ----------------');
  console.log(`case: ${m.c.name}`);
  console.log(`argv: ${fmtArgv(m.c.argv)}`);
  if (m.c.env?.COLUMNS) console.log(`env:  COLUMNS=${m.c.env.COLUMNS}`);
  console.log(`exit: ref=${m.refReal.code} refAlias=${m.refAlias.code} port=${m.port.code} ${m.okCode ? '(match)' : '(DIFFER)'}`);
  console.log(`stdout prog-normalized ${m.okNormOut ? 'match' : 'DIFFER'} | raw-same-prog ${m.okRawOut ? 'match' : 'DIFFER'}`);
  if (!m.okNormOut || !m.okRawOut) {
    console.log(`  ref (real prog, normalized): ${show(m.nOut)}`);
    console.log(`  ref (alias prog test7.mjs) : ${show(m.refAlias.stdout)}`);
    console.log(`  port                       : ${show(m.port.stdout)}`);
  }
  console.log(`stderr prog-normalized ${m.okNormErr ? 'match' : 'DIFFER'} | raw-same-prog ${m.okRawErr ? 'match' : 'DIFFER'}`);
  if (!m.okNormErr || !m.okRawErr) {
    console.log(`  ref (real prog, normalized): ${show(m.nErr)}`);
    console.log(`  ref (alias prog test7.mjs) : ${show(m.refAlias.stderr)}`);
    console.log(`  port                       : ${show(m.port.stderr)}`);
  }
}
if (!mismatches.length) console.log('\nALL CASES MATCH');
